"""Type Generation Script: Pydantic v2 Schemas -> TypeScript Types.

Generates `frontend/types/api.ts` from backend Pydantic schemas so that
the frontend maintains 100% type-safety and contract synchronization with the API.
"""

from pathlib import Path


def generate_typescript_contracts() -> str:
    """Generate TypeScript interface definitions matching backend Pydantic schemas."""
    ts_code = """/**
 * Auto-generated TypeScript definitions matching Backend Pydantic v2 Schemas.
 * Generated by `scripts/generate_types.py`. Do not edit directly.
 */

// Supported LiteLLM Model Identifiers
export enum ModelID {
  GEMINI_3_5_FLASH = "gemini/gemini-3.5-flash",
  GEMINI_3_8_FLASH = "gemini/gemini-3.8-flash",
  GROQ_GPT_OSS_120B = "groq/openai/gpt-oss-120b",
  GROQ_GPT_OSS_20B = "groq/openai/gpt-oss-20b",
  GROQ_QWEN_27B = "groq/qwen/qwen3.8-27b",
  GROQ_QWEN_32B = "groq/qwen/qwen3-32b",
  OLLAMA_LLAMA_3_2 = "ollama/llama3.2",
  OLLAMA_MISTRAL = "ollama/mistral",
  OLLAMA_PHI3 = "ollama/phi3",
}

export enum ModelProvider {
  GOOGLE = "google",
  GROQ = "groq",
  OLLAMA = "ollama",
}

export interface ModelInfo {
  model_id: ModelID;
  provider: ModelProvider;
  display_name: string;
  is_local: boolean;
}

// Task Classification Categories
export enum TaskType {
  SUMMARIZATION = "summarization",
  QUESTION_ANSWERING = "question_answering",
  CODE_GENERATION = "code_generation",
  DATA_EXTRACTION = "data_extraction",
  CREATIVE_WRITING = "creative_writing",
  CLASSIFICATION = "classification",
  TRANSLATION = "translation",
  RAG_RESPONSE = "rag_response",
  COMMAND_GENERATION = "command_generation",
}

// Feature Middleware Flags
export enum FeatureFlag {
  BASIC_SCORING = "basic_scoring",
  OBSERVABILITY = "observability",
  LLM_AS_JUDGE = "llm_as_judge",
  RAG_EVAL = "rag_eval",
  HALLUCINATION_DETECTION = "hallucination_detection",
}

// Metrics Evaluated
export enum ScoringMetric {
  BERT_SCORE = "bert_score",
  ROUGE_L = "rouge_l",
  LATENCY = "latency",
  TOKEN_COUNT = "token_count",
  ESTIMATED_COST = "estimated_cost",
  LLM_JUDGE = "llm_judge",
  HALLUCINATION_SCORE = "hallucination_score",
}

export interface EvalConsumerConfig {
  consumer_id: string;
  features: FeatureFlag[];
  models: ModelID[];
  task_type: TaskType;
  scoring_metrics: ScoringMetric[];
  timeout_seconds?: number;
  max_retries?: number;
}

// Evaluation Execution Requests & Responses
export interface PromptRunRequest {
  prompt: string;
  task_type?: TaskType;
  models: ModelID[];
  consumer_id?: string | null;
  consumer_config?: EvalConsumerConfig | null;
  scoring_metrics?: ScoringMetric[];
  reference_output?: string | null;
}

export interface ModelResponseSchema {
  model_id: ModelID;
  output: string;
  latency_ms: number;
  token_count: number;
  finish_reason?: string;
  from_cache?: boolean;
  attempt_number?: number;
  created_at?: string;
}

export interface EvalScoreSchema {
  model_id: ModelID;
  bert_score_f1?: number | null;
  rouge_l?: number | null;
  latency_ms: number;
  token_count: number;
  estimated_cost_usd: number;
  hallucination_score?: number | null;
  llm_judge_score?: number | null;
}

export interface EvalRunResult {
  run_id: string;
  prompt: string;
  task_type: TaskType;
  models: ModelID[];
  status: "pending" | "running" | "completed" | "failed";
  responses: ModelResponseSchema[];
  scores: EvalScoreSchema[];
  winner?: ModelID | null;
  created_at: string;
  completed_at?: string | null;
}

export interface EvalRunSummary {
  run_id: string;
  consumer_id?: string | null;
  task_type: TaskType;
  models: ModelID[];
  status: string;
  created_at: string;
  completed_at?: string | null;
}

export interface RunComparison {
  run_id_a: string;
  run_id_b: string;
  score_deltas: Record<string, Record<string, number | null>>;
}

// Leaderboard & Recommendations
export interface LeaderboardEntry {
  model_id: ModelID;
  task_type: TaskType;
  total_runs: number;
  win_rate: number;
  avg_bert_score?: number | null;
  avg_rouge_l?: number | null;
  avg_latency_ms: number;
  avg_token_count: number;
  total_estimated_cost_usd: number;
}

export interface LeaderboardResponse {
  task_type?: TaskType | null;
  entries: LeaderboardEntry[];
  from_cache: boolean;
  cached_at?: string | null;
}

export interface ModelRecommendation {
  task_type: TaskType;
  recommended_model: ModelID;
  metric: ScoringMetric;
  score?: number | null;
  reason: string;
}

// WebSocket Live Streaming Event
export interface StreamTokenEvent {
  run_id: string;
  model_id: string;
  token?: string;
  output?: string;
  latency_ms?: number;
  token_count?: number;
  finish_reason?: string;
  is_final: boolean;
}
"""
    return ts_code


def main() -> None:
    """Generate and write TypeScript definitions to frontend/types/api.ts."""
    out_dir = Path("frontend/types")
    out_dir.mkdir(parents=True, exist_ok=True)
    out_file = out_dir / "api.ts"

    content = generate_typescript_contracts()
    out_file.write_text(content, encoding="utf-8")
    print(f"Successfully generated TypeScript API definitions at {out_file.resolve()}")


if __name__ == "__main__":
    main()
